cat > purchase.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT p.id, p.created_at AS "createdAt", p.total_cents AS "totalCents",
      (SELECT coalesce(json_agg(json_build_object('bookId', pl.book_id, 'title', b.title,
          'quantity', pl.quantity, 'unitPriceCents', pl.unit_price_cents) ORDER BY pl.id), '[]'::json)
        FROM purchase_line pl JOIN book b ON b.id = pl.book_id WHERE pl.purchase_id = p.id) AS lines
    FROM purchase p
    WHERE p.customer_id = ${ctx.get("customer")}`;
}
EOF
cat > purchase.command.ts <<'EOF'
// Only create exists: PATCH, PUT and DELETE answer 405.
// Everything runs in one transaction: a reject or a failed payment rolls back all writes.
export function create(input, ctx) {
  const customerId = ctx.get("customer");
  const quantities = {};
  const bookIds = [];
  for (const line of input.lines) {
    if (quantities[line.bookId] === undefined) {
      quantities[line.bookId] = 0;
      bookIds.push(line.bookId);
    }
    quantities[line.bookId] += line.quantity;
  }

  const books = {};
  const rows = ctx.db.query(ctx.sql`SELECT id, price_cents AS "priceCents", stock, published
    FROM book WHERE id = ANY(${bookIds}) ORDER BY id FOR UPDATE`);
  for (const row of rows) books[row.id] = row;

  for (const bookId of bookIds) {
    const book = books[bookId];
    if (!book || !book.published) {
      ctx.reject({ message: `book ${bookId} is not available`, pointer: "/lines", status: 422 });
    }
    if (book.stock < quantities[bookId]) {
      ctx.reject({ message: `not enough stock for book ${bookId}`, pointer: "/lines", status: 409, code: "insufficient_stock" });
    }
  }

  let totalCents = 0;
  for (const line of input.lines) {
    totalCents += books[line.bookId].priceCents * line.quantity;
  }

  const res = ctx.fetch("http://127.0.0.1:18090/payments", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: { customerId: customerId, amountCents: totalCents },
  });
  if (!res.ok) ctx.reject({ message: "payment service failed", status: 502, code: "payment_failed" });
  let answer = null;
  try {
    answer = JSON.parse(res.text()).status;
  } catch (e) {
    answer = null;
  }
  if (answer === "declined") ctx.reject({ message: "payment declined", status: 402, code: "payment_declined" });
  if (answer !== "accepted") ctx.reject({ message: "payment service failed", status: 502, code: "payment_failed" });

  const [purchase] = ctx.db.query(ctx.sql`INSERT INTO purchase (customer_id, total_cents)
    VALUES (${customerId}, ${totalCents}) RETURNING id`);
  for (const line of input.lines) {
    const book = books[line.bookId];
    ctx.db.exec(ctx.sql`INSERT INTO purchase_line (purchase_id, book_id, quantity, unit_price_cents)
      VALUES (${purchase.id}, ${line.bookId}, ${line.quantity}, ${book.priceCents})`);
    ctx.db.exec(ctx.sql`UPDATE book SET stock = stock - ${line.quantity} WHERE id = ${line.bookId}`);
  }
  return purchase.id;
}
EOF
