cat > report.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  const from = ctx.get("from");
  const to = ctx.get("to");
  if (from !== null && to !== null && from > to) {
    ctx.reject({ message: "from must not be after to", pointer: "/from", status: 400, code: "invalid_parameter" });
  }
  return ctx.sql`SELECT b.title, sum(pl.quantity)::int AS quantity,
      sum(pl.quantity * pl.unit_price_cents)::bigint AS "revenueCents"
    FROM purchase_line pl
    JOIN purchase p ON p.id = pl.purchase_id
    JOIN book b ON b.id = pl.book_id
    WHERE (p.created_at AT TIME ZONE 'UTC')::date BETWEEN ${from}::date AND ${to}::date
    GROUP BY b.id, b.title
    ORDER BY "revenueCents" DESC, b.title, b.id`;
}
EOF
